#!/usr/bin/env python3
"""S44 audit, HYP-9315(a): is H_1 of the Koszul complex of the jets f_n = d^n x_0^N cyclic over C[x][d], generated by
the Euler syzygy s_1 = x_0 e_1 - N x_1 e_0?  Independent code (ascending monomials, vcore.py).
For every bidegree (weight D, length r): dim Z_1, dim B_1, dim H_1, and dim (span{m d^k s_1} + B_1)/B_1.
Additionally reports the total-weight H_1 dimensions (to compare with kind-pasteur's table for N = 3, 4) and the
N-stability count  dim Z_1 (weight 2N+m) = sum_{n=3}^m p_{>=2}(m-n)  for m < 2N+1.
Usage: python koszul_cyclic_audit.py N Dmax [P]
"""
import sys, json, time
import flint
from vcore import parts, block_index, dpoly, polymul_mono, asc


def main():
    N, Dmax = int(sys.argv[1]), int(sys.argv[2])
    P = int(sys.argv[3]) if len(sys.argv) > 3 else 2147483647
    f = [{(2,) * N: 1}]
    while len(f) <= Dmax - 2 * N:
        f.append(dpoly(f[-1], P))

    def k1(D, r):
        return [(n, m) for n in range(0, D - 2 * N + 1) for m in parts(D - 2 * N - n) if len(m) == r - N]

    def rank(rows, n):
        if not rows or not n:
            return 0
        return flint.nmod_mat(len(rows), n, [x for r in rows for x in r], P).rank()

    def dK(el):
        """d on K_1: d(g e_n) = (dg) e_n + g e_(n+1)."""
        out = {}
        for (n, m), co in el.items():
            for mm, c2 in dpoly({m: 1}, P).items():
                out[(n, mm)] = (out.get((n, mm), 0) + co * c2) % P
            out[(n + 1, m)] = (out.get((n + 1, m), 0) + co) % P
        return {k: v for k, v in out.items() if v}

    s1 = {(1, (2,)): 1, (0, (3,)): (-N) % P}
    # d^k s1
    dks = [s1]
    while 2 * N + 3 + len(dks) - 1 < Dmax:
        dks.append(dK(dks[-1]))
    rows_out = []
    ok = True
    tot = {}
    t0 = time.time()
    for D in range(2 * N + 1, Dmax + 1):
        for r in range(N + 1, D // 2 + 1):
            B = k1(D, r)
            if not B:
                continue
            i1 = {b: i for i, b in enumerate(B)}
            idx = block_index(D, r)
            d1 = []
            for (n, m) in B:
                row = [0] * len(idx)
                for mono, co in polymul_mono(f[n], m).items():
                    row[idx[mono]] = (row[idx[mono]] + co) % P
                d1.append(row)
            dimZ = len(B) - rank(d1, len(idx))
            # boundaries
            br = []
            nf = D - 2 * N + 1
            for a in range(nf):
                for b in range(a + 1, nf):
                    w = D - 4 * N - a - b
                    if w < 0 or r - 2 * N < 0:
                        continue
                    for m in parts(w):
                        if len(m) != r - 2 * N:
                            continue
                        row = [0] * len(B)
                        for mono, co in f[a].items():
                            j = i1[(b, asc(mono + m))]
                            row[j] = (row[j] + co) % P
                        for mono, co in f[b].items():
                            j = i1[(a, asc(mono + m))]
                            row[j] = (row[j] - co) % P
                        br.append(row)
            rkB = rank(br, len(B))
            h1 = dimZ - rkB
            # generated part: m * d^k s1 with wt(m) + k + 2N + 3 = D, len(m) + N + 1 = r
            gr = []
            for k in range(0, D - (2 * N + 3) + 1):
                wm = D - (2 * N + 3) - k
                for m in parts(wm):
                    if len(m) != r - N - 1:
                        continue
                    if k >= len(dks):
                        continue
                    row = [0] * len(B)
                    for (n, mm), co in dks[k].items():
                        key = (n, asc(mm + m))
                        row[i1[key]] = (row[i1[key]] + co) % P
                    gr.append(row)
            span = rank(br + gr, len(B)) - rkB if gr else 0
            # every generated element must be a cycle: check d1 of generated rows vanish
            for row in gr:
                img = [0] * len(idx)
                for j, co in enumerate(row):
                    if co:
                        for t in range(len(idx)):
                            pass
                # (cycle property is automatic: d1 commutes with d and C[x]; s1 is a cycle; verified below once)
            if h1 or span:
                rows_out.append(dict(D=D, r=r, Z=dimZ, B=rkB, H1=h1, span=span))
                tot[D] = tot.get(D, 0) + h1
                if span != h1:
                    ok = False
    # verify s1 is a cycle
    chk = {}
    for (n, m), co in s1.items():
        for mono, c2 in polymul_mono(f[n], m).items():
            chk[mono] = (chk.get(mono, 0) + co * c2) % P
    assert not any(chk.values()), 's1 not a cycle'
    print('N=%d D<=%d P=%d: H_1 generated by s_1 over C[x][d] (mod boundaries) at every bidegree: %s  (%.1fs)' % (N, Dmax, P, ok, time.time() - t0))
    print('  total-weight dim H_1:', [(D, tot[D]) for D in sorted(tot)])
    bad = [x for x in rows_out if x['H1'] != x['span']]
    print('  mismatches:', bad[:10])
    # N-stability of Z_1 below 4N+1
    def p2(k):
        return len(parts(k)) if k >= 0 else 0
    stab = []
    for D in range(2 * N + 3, min(Dmax, 4 * N) + 1):
        m = D - 2 * N
        pred = sum(p2(m - n) for n in range(3, m + 1))
        got = sum(x['Z'] for x in rows_out if x['D'] == D)
        stab.append((D, got, pred))
    print('  dim Z_1 vs sum_{n=3}^m p2(m-n) for D < 4N+1:', stab, 'all equal:', all(g == p for _, g, p in stab))
    json.dump(dict(N=N, Dmax=Dmax, P=P, ok=ok, rows=rows_out), open('koszul_cyclic_audit_N%d_D%d.json' % (N, Dmax), 'w'), indent=1)


if __name__ == '__main__':
    main()
